// Entry gate: checks the shared secret, the file and the daily cap, then builds the Gemini request.
// Never throws: every branch returns a clean JSON answer instead of failing halfway.
const MODEL = 'gemini-3.1-flash-lite';            // change the model in this one place
const SHARED_SECRET = 'REPLACE_WITH_SHARED_SECRET';
const MAX_BYTES = 10 * 1024 * 1024;               // keep in sync with the upload app's max file size
const DAILY_LIMIT = 60;                           // max extractions per day (cost guard)
const ALLOWED = { 'application/pdf': 'document', 'image/png': 'image', 'image/jpeg': 'image' };

const item = $input.first();
const headers = item.json.headers || {};
const reject = (status, error) => [{ json: { ok: false, status, error } }];

if (String(headers['x-demo-secret'] || '') !== SHARED_SECRET) return reject(401, 'Unauthorized.');

const binaries = item.binary || {};
const key = binaries.invoice ? 'invoice' : Object.keys(binaries)[0];
if (!key) return reject(400, 'No file received.');

const meta = binaries[key] || {};
const mime = String(meta.mimeType || '').toLowerCase();
const kind = ALLOWED[mime];
if (!kind) return reject(415, 'Only PDF, JPG or PNG files are accepted.');

let buf = null;
if (meta.data && !meta.id) { try { buf = Buffer.from(meta.data, 'base64'); } catch (e) { buf = null; } }
if (!buf || !buf.length) {
  try { buf = await this.helpers.getBinaryDataBuffer(0, key); }
  catch (e) { return reject(500, 'Could not read the uploaded file.'); }
}
if (!buf || !buf.length) return reject(400, 'The file is empty.');
if (buf.length > MAX_BYTES) return reject(413, 'That file is larger than 10 MB.');

// Do not trust the browser's Content-Type: check magic bytes
const head = buf.subarray(0, 8);
const isPdf = head.subarray(0, 4).toString('latin1') === '%PDF';
const isPng = head.length >= 8 && head.equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]));
const isJpg = head[0] === 0xff && head[1] === 0xd8 && head[2] === 0xff;
if (!((mime === 'application/pdf' && isPdf) || (mime === 'image/png' && isPng) || (mime === 'image/jpeg' && isJpg))) {
  return reject(415, 'That file does not look like a PDF, JPG or PNG.');
}

// Daily cap stored in workflow static data (no database needed)
const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (store.day !== today) { store.day = today; store.count = 0; }
store.count = (store.count || 0) + 1;
if (store.count > DAILY_LIMIT) {
  return reject(429, 'The demo has reached its daily limit. Please try again tomorrow, or contact the site owner.');
}

const schema = {
  type: 'object',
  properties: {
    not_an_invoice: { type: 'boolean', description: 'true if the document is not an invoice, bill or receipt' },
    vendor: { type: 'string', description: 'Name of the company issuing the invoice' },
    vendor_address: { type: 'string' },
    invoice_number: { type: 'string' },
    invoice_date: { type: 'string', description: 'ISO date YYYY-MM-DD' },
    due_date: { type: 'string', description: 'ISO date YYYY-MM-DD, empty if absent' },
    currency: { type: 'string', description: 'ISO 4217 code such as USD, AUD, EUR' },
    subtotal: { type: 'number' },
    tax: { type: 'number' },
    total: { type: 'number' },
    line_items: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          description: { type: 'string' },
          qty: { type: 'number' },
          unit_price: { type: 'number' },
          amount: { type: 'number' },
        },
        required: ['description', 'amount'],
      },
    },
    notes: { type: 'string', description: 'Anything unusual: handwriting, stamps, unreadable areas' },
  },
  required: ['not_an_invoice', 'vendor', 'invoice_number', 'invoice_date', 'currency', 'total', 'line_items'],
};

const prompt = [
  'Extract the fields of this supplier invoice.',
  'Rules:',
  '- Use only what is printed in the document. Never invent a value.',
  '- Numbers must be plain numbers: no currency symbol, no thousands separator, dot as decimal mark.',
  '- Dates in ISO format YYYY-MM-DD. If a date is written day/month/year, convert it.',
  '- If a field is not present, use an empty string for text and 0 for numbers you cannot read.',
  '- line_items: one entry per billed line; ignore subtotal, tax and total rows.',
  '- If the document is not an invoice, bill or receipt, set not_an_invoice to true and leave the other fields empty.',
  '- If part of the document is unreadable, say so in notes instead of guessing.',
].join('\n');

return [{
  json: {
    ok: true,
    request_id: 'inv-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 7),
    received_at: new Date().toISOString(),
    source: String((item.json.body && item.json.body.source) || 'unknown').slice(0, 60),
    file_name: String(meta.fileName || 'upload').slice(0, 120),
    file_type: mime,
    file_size: buf.length,
    model: MODEL,
    geminiBody: {
      model: MODEL,
      system_instruction: 'You are an accounts-payable data extraction service. You return only the structured fields requested, taken verbatim from the document.',
      input: [
        { type: 'text', text: prompt },
        { type: kind, data: buf.toString('base64'), mime_type: mime },
      ],
      response_format: { type: 'text', mime_type: 'application/json', schema },
      generation_config: { temperature: 0, max_output_tokens: 2000 },
    },
  },
}];

// Read the Gemini answer, coerce numbers, reconcile totals, sanitise strings before writing to the sheet.
// Every error branch returns valid JSON to the caller; nothing throws.
const gate = $('Check request').first().json;
const raw = $json || {};
const started = Date.parse(gate.received_at || '') || Date.now();

const clean = (v, max = 200) => String(v == null ? '' : v).split('').filter((ch) => ch.charCodeAt(0) > 31 && ch.charCodeAt(0) !== 127).join('').trim().slice(0, max);
const sheetSafe = (v) => (/^[=+\-@\t\r]/.test(v) ? "'" + v : v);          // block formula injection in Google Sheets
const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
const num = (v) => {
  if (typeof v === 'number' && Number.isFinite(v)) return round2(v);
  if (typeof v !== 'string') return null;
  const s = v.replace(/[^0-9.,\-]/g, '').replace(/,(?=\d{3}\b)/g, '').replace(',', '.');
  const n = Number.parseFloat(s);
  return Number.isFinite(n) ? round2(n) : null;
};

function geminiText(r) {
  const out = [];
  const walk = (steps) => {
    for (const s of steps || []) for (const c of s.content || []) if (typeof c.text === 'string') out.push(c.text);
  };
  if (Array.isArray(r.steps)) walk(r.steps);
  if (!out.length && Array.isArray(r.output)) walk(r.output);
  if (!out.length && Array.isArray(r.candidates)) {
    for (const c of r.candidates) for (const p of (c.content && c.content.parts) || []) if (p.text) out.push(p.text);
  }
  return out.join('').trim();
}

const base = {
  request_id: gate.request_id,
  file: { name: gate.file_name, type: gate.file_type, size_kb: Math.round((gate.file_size || 0) / 1024) },
  model: gate.model,
};

const fail = (message) => {
  const response = Object.assign({}, base, { ok: false, error: message, validation: { ok: false, issues: [message] } });
  return [{ json: { response, row: null, failed: true } }];
};

if (raw.error || raw.status === 'failed') {
  return fail('The extraction service did not answer. Please try again in a minute.');
}

let text = geminiText(raw);
if (!text) return fail('The model returned an empty answer. Please try another file.');
text = text.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

const unreadable = 'The model did not return readable data. Please try another file.';
let ex = null;
try { ex = JSON.parse(text); } catch (e) {
  const m = text.match(/\{[\s\S]*\}/);
  if (!m) return fail(unreadable);
  try { ex = JSON.parse(m[0]); } catch (e2) { return fail(unreadable); }
}
if (!ex || typeof ex !== 'object' || Array.isArray(ex)) return fail(unreadable);
// No core field at all => treat the model output as garbage; never write an empty row
if (ex.not_an_invoice !== true && !ex.vendor && !ex.total && !ex.invoice_number && !Array.isArray(ex.line_items)) {
  return fail(unreadable);
}

if (ex.not_an_invoice === true) {
  const response = Object.assign({}, base, {
    ok: false,
    error: 'That file does not look like an invoice. Try one of the sample invoices.',
    validation: { ok: false, issues: ['not an invoice'] },
  });
  return [{ json: { response, row: null, failed: true } }];
}

const items = Array.isArray(ex.line_items) ? ex.line_items.slice(0, 40) : [];
const line_items = items.map((i) => ({
  description: clean(i && i.description, 120),
  qty: num(i && i.qty),
  unit_price: num(i && i.unit_price),
  amount: num(i && i.amount),
}));

const fields = {
  vendor: clean(ex.vendor, 120),
  vendor_address: clean(ex.vendor_address, 200),
  invoice_number: clean(ex.invoice_number, 60),
  invoice_date: clean(ex.invoice_date, 20),
  due_date: clean(ex.due_date, 20),
  currency: clean(ex.currency, 8).toUpperCase(),
  subtotal: num(ex.subtotal),
  tax: num(ex.tax),
  total: num(ex.total),
  notes: clean(ex.notes, 300),
};

// Reconciliation: the LLM reads, code checks the maths.
const issues = [];
const TOL = 0.02;
const lineSum = line_items.length ? round2(line_items.reduce((a, i) => a + (i.amount || 0), 0)) : null;
if (!fields.total) issues.push('no total found');
if (!fields.vendor) issues.push('no vendor name found');
if (!fields.invoice_date) issues.push('no invoice date found');
if (lineSum != null && fields.subtotal != null && Math.abs(lineSum - fields.subtotal) > TOL) {
  issues.push('line items add up to ' + lineSum.toFixed(2) + ' but subtotal says ' + fields.subtotal.toFixed(2));
}
if (fields.subtotal != null && fields.tax != null && fields.total != null &&
    Math.abs(round2(fields.subtotal + fields.tax) - fields.total) > TOL) {
  issues.push('subtotal + tax = ' + round2(fields.subtotal + fields.tax).toFixed(2) + ' but total says ' + fields.total.toFixed(2));
}
if (lineSum != null && fields.subtotal == null && fields.tax == null && fields.total != null &&
    Math.abs(lineSum - fields.total) > TOL) {
  issues.push('line items add up to ' + lineSum.toFixed(2) + ' but total says ' + fields.total.toFixed(2));
}

const usage = raw.usage || {};
const response = Object.assign({}, base, fields, {
  ok: true,
  line_items,
  line_item_sum: lineSum,
  validation: { ok: issues.length === 0, issues },
  latency_ms: Date.now() - started,
  tokens: { in: usage.total_input_tokens != null ? usage.total_input_tokens : null, out: usage.total_output_tokens != null ? usage.total_output_tokens : null },
});

const row = {
  request_id: gate.request_id,
  received_at: gate.received_at,
  source: sheetSafe(clean(gate.source, 60)),
  file_name: sheetSafe(clean(gate.file_name, 120)),
  file_type: gate.file_type,
  vendor: sheetSafe(fields.vendor),
  invoice_number: sheetSafe(fields.invoice_number),
  invoice_date: sheetSafe(fields.invoice_date),
  currency: sheetSafe(fields.currency),
  subtotal: fields.subtotal != null ? fields.subtotal : '',
  tax: fields.tax != null ? fields.tax : '',
  total: fields.total != null ? fields.total : '',
  line_item_count: line_items.length,
  reconciled: issues.length === 0 ? 'yes' : 'no',
  issues: sheetSafe(clean(issues.join(' | '), 400)),
  model: gate.model,
  latency_ms: response.latency_ms,
  tokens_in: response.tokens.in != null ? response.tokens.in : '',
  tokens_out: response.tokens.out != null ? response.tokens.out : '',
};

return [{ json: { response, row, failed: false } }];

// Google Sheets (Map Automatically) only sees top-level fields,
// so flatten the row into one item whose keys match the 19 sheet columns.
const row = $input.first().json.row || {};
return [{ json: row }];
